xmax = 4,
ymin = -18,
ymax = 18,
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above right},
]

\addplot [
domain=-25:6,
samples=100,
color=blue,
line width=1pt,
]{(x+4)};

